sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    // Exit early if form is loading, template is being applied, or value hasn't changed
    if (isLoading || isTemplate || newValue === oldValue) {
        return;
    }
    try {
		//Clear New Settlement Date field value
		g_form.clearValue('new_settlement_date');

        // clear comments field
        g_form.setValue('comments', '');
		g_form.setValue('u_martini_reference_1', '');
		g_form.setValue('u_martini_reference_2', '');
    } catch (e) {
        //SILENT FALL
    }
}
